inline bool is_physics3_dstatic_surface_collider(flight::Ref<Physics3DCollider> collider) {
  const auto kind = std::visit([](const auto& shape) { return shape->kind; }, collider->local);
  return kind == flight::String("triangle-mesh") || kind == flight::String("heightfield");
}

