inline bool is_physics3_dgravity_valid(flight::Ref<Physics3DWorld> world) {
  return ((std::isfinite(world->gravity_x) && std::isfinite(world->gravity_y)) && std::isfinite(world->gravity_z));
}

inline bool is_physics3_dposition_iterations_valid(flight::Ref<Physics3DSolverConfig> config) {
  const double iterations = config->sequential_impulse->position_iterations;
  return (flight::is_safe_integer(iterations) && (iterations >= 0.0));
}


